        return '<saml:AuthnStatement AuthnInstant="' + authnInstant + '" SessionIndex="' + sessionIndex + '">' +
               '<saml:AuthnContext>' +
               '<saml:AuthnContextClassRef>urn:oasis:names:tc:SAML:2.0:ac:classes:PasswordProtectedTransport</saml:AuthnContextClassRef>' +
               '</saml:AuthnContext>' +
               '</saml:AuthnStatement>';
